import unittest

from hourglass.rounding import rounded_labels
from hourglass.models import Span


def labels(start, end, step=15):
    return rounded_labels([Span(start, end)], step)


class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(labels(8 * 60 + 53, 17 * 60 + 10), ["09:00-17:15 (8h 15m)"])
        self.assertEqual(labels(8 * 60 + 7, 9 * 60 + 8, 5), ["08:05-09:10 (1h 05m)"])

    def test_halves_round_up_and_order_is_kept(self):
        self.assertEqual(labels(67, 120, 15)[0][:5], "01:15")
        self.assertEqual(len(rounded_labels([Span(0, 60), Span(60, 120)], 30)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                labels(0, 60, step)
